from pathlib import Path
import re

root=Path(__file__).resolve().parents[1]
main=root/'src/main.jsx'
css=root/'src/app.css'
src=main.read_text(encoding='utf-8')

# Generate trainer passwords automatically, while keeping the existing backend function contract.
user_form=r'''function UserForm({onSubmit,role}){const[tempPassword]=useState(()=>{const sets=["ABCDEFGHJKLMNPQRSTUVWXYZ","abcdefghijkmnopqrstuvwxyz","23456789","!@#$%^&*()-_=+"];const all=sets.join("");const bytes=new Uint32Array(16);crypto.getRandomValues(bytes);const chars=sets.map((set,i)=>set[bytes[i]%set.length]);for(let i=4;i<16;i++)chars.push(all[bytes[i]%all.length]);for(let i=chars.length-1;i>0;i--){const j=bytes[i%bytes.length]%(i+1);[chars[i],chars[j]]=[chars[j],chars[i]]}return chars.join("")});return <form onSubmit={onSubmit} className="form"><label>Full name<input name="full_name" required/></label><label>{role==="member"?"Member ID":"Trainer ID"}<input name="login_id" required placeholder={role==="member"?"MEM001":"TRN001"}/></label><label>Phone<input name="phone" inputMode="tel"/></label><label>Email <small>(optional)</small><input name="email" type="email" placeholder="staff@example.com"/></label><input type="hidden" name="password" value={tempPassword}/><div className="generated-credential-note"><b>Temporary password generated automatically</b><span>The account holder changes it after first login.</span></div><input type="hidden" name="role" value={role}/><button className="primary wide">Create {role}</button></form>}'''
pattern=r'function UserForm\(\{onSubmit,role\}\).*?function PeopleTable'
src,n=re.subn(pattern,user_form+'function PeopleTable',src,count=1,flags=re.S)
assert n==1, 'UserForm function not found'

# Remove redundant top-level transaction creation buttons.
src=src.replace('{tab==="Payments"&&<button className="primary page-action" onClick={()=>setModal("payment")}>+ Record payment</button>}','')
src=src.replace('{tab==="Memberships"&&<button className="primary page-action" onClick={()=>setModal("membership")}>+ Assign membership</button>}','')
src=src.replace('<small>Fees received and payment records.</small>','<small>Payments are recorded automatically when members join, renew or settle a due.</small>')
src=src.replace('<small>Members can stay registered while payment is pending. Collect the balance here.</small>','<small>Outstanding membership payments appear here. Select a member to settle their balance.</small>')
src=src.replace('>Collect payment</button>','>Settle due</button>')

# Replace only the Owner dashboard JSX; all backend state, handlers, RPCs and modals remain in place.
start=src.find('{tab==="Dashboard"&&<>')
end=src.find('{tab==="Members"&&<PeopleTable',start)
assert start!=-1 and end!=-1, 'Dashboard block not found'
dashboard=r'''{tab==="Dashboard"&&<><section className="owner-welcome"><div><span className="owner-kicker">TODAY AT {gym?.name||"YOUR GYM"}</span><h1>Run your gym.</h1><p>Everything important, without the clutter.</p></div><button className="primary owner-primary-action" onClick={()=>setModal("member")}>+ Register member</button></section><section className="owner-stat-row"><button className="owner-stat" onClick={()=>setDashboardDrill("members")}><span>Members</span><b>{mo.length}</b><small>View all</small></button><button className="owner-stat" onClick={()=>setDashboardDrill("present")}><span>Checked in</span><b>{memberPresent}</b><small>Today</small></button><button className="owner-stat" onClick={()=>setDashboardDrill("payments")}><span>Collected</span><b>{money(todayCollection)}</b><small>Today</small></button></section><section className="owner-quick-grid"><button onClick={()=>setModal("member")}><span>＋</span><b>Register member</b><small>Member + membership + payment</small></button><button onClick={()=>setTab("Attendance")}><span>✓</span><b>Attendance</b><small>Today's check-ins</small></button><button onClick={()=>setTab("Members")}><span>◉</span><b>Members</b><small>Search and manage</small></button><button onClick={()=>setTab("Trainers")}><span>◎</span><b>Trainers</b><small>Manage trainer accounts</small></button></section><section className="owner-attention"><div className="section-top"><div><span className="owner-section-kicker">NEEDS ATTENTION</span><h3>Keep the gym running</h3></div><span className="attention-count">{(gym?.latitude&&gym?.longitude?0:1)+(pendingTotal>0?1:0)+(expiresTomorrow>0?1:0)}</span></div><div className="attention-list">{(!gym?.latitude||!gym?.longitude)&&<button onClick={()=>setModal("settings")}><span className="attention-icon warning">!</span><div><b>Complete gym location</b><small>Check-in needs a configured gym location.</small></div><i>›</i></button>}{pendingTotal>0&&<button onClick={()=>setTab("Dues")}><span className="attention-icon danger">₹</span><div><b>{money(pendingTotal)} payment due</b><small>Open dues and settle outstanding payments.</small></div><i>›</i></button>}{expiresTomorrow>0&&<button onClick={()=>setRenewalList("tomorrow")}><span className="attention-icon">!</span><div><b>{expiresTomorrow} membership{expiresTomorrow===1?"":"s"} expire tomorrow</b><small>Open the list and follow up.</small></div><i>›</i></button>}{gym?.latitude&&gym?.longitude&&pendingTotal===0&&expiresTomorrow===0&&<div className="attention-clear"><span>✓</span><div><b>You're all caught up</b><small>No immediate action is required.</small></div></div>}</div></section><section className="owner-secondary-row"><button onClick={()=>setTab("Memberships")}><span>Memberships</span><b>{active}</b><small>Active members</small></button><button onClick={()=>setTab("Reports")}><span>Reports</span><b>{money(pendingTotal)}</b><small>Outstanding dues</small></button><button onClick={()=>setTab("Settings")}><span>Gym setup</span><b>{gym?.latitude&&gym?.longitude?"Ready":"Action"}</b><small>Location & check-in rules</small></button></section></>}
'''
src=src[:start]+dashboard+src[end:]

# Automatically generated Gym Owner password. Existing super-admin-create-gym backend receives it through FormData.
create_form_pattern=r'<form className="form" onSubmit=\{createGym\}>.*?</form>'
create_form=r'''<GymCreateForm busy={busy} onSubmit={createGym} suggestId={suggestId}/>'''
src,n=re.subn(create_form_pattern,create_form,src,count=1,flags=re.S)
assert n==1, 'Create Gym form not found'
gym_form=r'''function GymCreateForm({busy,onSubmit,suggestId}){const[tempPassword]=useState(()=>{const sets=["ABCDEFGHJKLMNPQRSTUVWXYZ","abcdefghijkmnopqrstuvwxyz","23456789","!@#$%^&*()-_=+"];const all=sets.join("");const bytes=new Uint32Array(20);crypto.getRandomValues(bytes);const chars=sets.map((set,i)=>set[bytes[i]%set.length]);for(let i=4;i<20;i++)chars.push(all[bytes[i]%all.length]);for(let i=chars.length-1;i>0;i--){const j=bytes[i%bytes.length]%(i+1);[chars[i],chars[j]]=[chars[j],chars[i]]}return chars.join("")});return <form className="form" onSubmit={onSubmit}><label>Gym name<input name="gym_name" required placeholder="Bodyline Gym" onChange={e=>{const id=e.currentTarget.form?.elements.login_id;if(id&&!id.dataset.edited)id.value=suggestId(e.target.value)}}/></label><label>Gym Owner name<input name="owner_name" required placeholder="Owner full name"/></label><label>Owner phone<input name="owner_phone" type="tel" placeholder="10-digit mobile number"/></label><label>Owner email<input name="owner_email" type="email" required placeholder="owner@example.com"/><small>This email receives the welcome email and login details.</small></label><label>Owner Login ID<input name="login_id" defaultValue="GYM01" onInput={e=>e.currentTarget.dataset.edited="true"}/><small>Generated from the gym name.</small></label><input type="hidden" name="password" value={tempPassword}/><div className="generated-credential-note"><b>Secure temporary password generated automatically</b><span>It is shown once after creation. The owner must change it after login.</span></div><button className="primary wide" disabled={busy}>{busy?"Creating…":"Create Gym + Owner"}</button></form>}'''
src=src.replace('function SuperAdminApp({profile}){',gym_form+'\nfunction SuperAdminApp({profile}){',1)
main.write_text(src,encoding='utf-8')

css_text=css.read_text(encoding='utf-8')
if '/* GYM MANAGER OWNER V2 */' not in css_text:
    css_text += r'''

/* GYM MANAGER OWNER V2 */
.admin-app{background:#f6f7f9;color:#18202c;min-height:100vh}.admin-app .admin-sidebar{position:fixed;inset:0 0 auto 0;width:100%;height:72px;z-index:60;display:flex;flex-direction:row;align-items:center;padding:0 24px;background:#0d1522;border:0;border-bottom:1px solid #243044;box-shadow:0 8px 24px #0b122018}.admin-app .sidebar-brand{border:0;background:none;color:#fff;display:flex;align-items:center;gap:10px;padding:0;cursor:pointer}.admin-app .brand-mark{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;background:linear-gradient(135deg,#f5d47b,#b77917);color:#17120a;font-weight:900;font-size:11px}.admin-app .sidebar-brand b{display:block;font-size:13px;letter-spacing:1.4px}.admin-app .sidebar-brand small{display:block;color:#8b98aa;font-size:9px;letter-spacing:1.2px;margin-top:2px}.admin-app .workspace-card{margin:0 54px 0 auto;padding:9px 13px;border:1px solid #2a3547;border-radius:12px;background:#ffffff08;display:flex;align-items:center;gap:9px;color:#fff}.admin-app .workspace-card small{display:block;color:#8793a5;font-size:9px;text-transform:uppercase;letter-spacing:1px}.admin-app .workspace-card strong{display:block;font-size:12px;margin-top:2px}.admin-app .workspace-dot{width:7px;height:7px;border-radius:50%;background:#3ddc97}.admin-app .admin-sidebar>.admin-nav,.admin-app .sidebar-footer{display:none}.admin-app .admin-main{padding:100px 28px 54px;max-width:1180px;margin:0 auto;width:100%}.admin-app .admin-page-header{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin-bottom:18px}.admin-app .page-heading .eyebrow{font-size:0}.admin-app .page-heading .eyebrow:after{content:"GYM MANAGER";font-size:10px;letter-spacing:1.8px;font-weight:800;color:#8a94a4}.admin-app .page-heading h2{font-size:31px;letter-spacing:-.7px;margin:5px 0 4px;color:#111927}.admin-app .page-heading p{margin:0;color:#7a8494;font-size:12px}.admin-app .mobile-menu-floating{position:fixed;right:18px;top:16px;z-index:80;width:40px;height:40px;border-radius:11px;border:1px solid #344258;background:#172234;color:#fff;display:grid;place-content:center;gap:4px;box-shadow:0 8px 20px #0003}.admin-app .mobile-menu-floating span{width:16px;height:2px;background:#fff;border-radius:2px}.admin-app .owner-welcome{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:27px 28px;border-radius:20px;background:linear-gradient(135deg,#111c2c,#1d2b40);color:#fff;margin-bottom:15px;box-shadow:0 16px 35px #11182718}.owner-kicker,.owner-section-kicker{font-size:9px;letter-spacing:1.8px;font-weight:800;color:#91a0b4}.admin-app .owner-welcome h1{font-size:29px;margin:7px 0 4px}.admin-app .owner-welcome p{margin:0;color:#aeb8c7;font-size:13px}.owner-primary-action{white-space:nowrap;border-radius:11px;background:#f5d47b;color:#18120a}.owner-stat-row{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:15px}.owner-stat{border:1px solid #e3e7ed;background:#fff;border-radius:15px;padding:17px 18px;text-align:left;cursor:pointer;box-shadow:0 7px 20px #11182708}.owner-stat span,.owner-stat small{display:block;color:#7b8492;font-size:11px}.owner-stat b{display:block;font-size:25px;color:#151d29;margin:6px 0 2px}.owner-quick-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:15px}.owner-quick-grid button,.owner-secondary-row button{border:1px solid #e2e6ec;background:#fff;border-radius:15px;padding:16px;text-align:left;cursor:pointer;box-shadow:0 7px 20px #11182707}.owner-quick-grid button>span{width:32px;height:32px;border-radius:10px;display:grid;place-items:center;background:#eef2f7;color:#1f2c3d;font-size:18px;margin-bottom:12px}.owner-quick-grid b,.owner-secondary-row b{display:block;font-size:13px;color:#17202d}.owner-quick-grid small,.owner-secondary-row small{display:block;color:#858e9b;font-size:10px;margin-top:4px}.owner-attention{background:#fff;border:1px solid #e2e6ec;border-radius:17px;padding:18px 19px;margin-bottom:15px;box-shadow:0 8px 25px #11182707}.owner-attention h3{margin:4px 0 0;font-size:16px}.attention-count{min-width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#f0f2f5;color:#344054;font-size:11px;font-weight:800}.attention-list{margin-top:12px}.attention-list>button,.attention-clear{width:100%;display:flex;align-items:center;gap:11px;padding:12px 3px;border:0;border-top:1px solid #eef0f3;background:transparent;text-align:left;cursor:pointer}.attention-icon{width:32px;height:32px;flex:0 0 32px;border-radius:10px;display:grid;place-items:center;background:#eef2f7;color:#334155;font-weight:800}.attention-icon.warning{background:#fff7df;color:#8a6200}.attention-icon.danger{background:#fff0f0;color:#b42318}.attention-list b{display:block;font-size:12px}.attention-list small,.attention-clear small{display:block;color:#858e9b;font-size:10px;margin-top:3px}.attention-list i{margin-left:auto;font-style:normal;font-size:20px;color:#9aa3af}.attention-clear>span{width:32px;height:32px;border-radius:10px;display:grid;place-items:center;background:#ecfdf5;color:#047857}.owner-secondary-row{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.owner-secondary-row span{font-size:10px;color:#7b8492;text-transform:uppercase;letter-spacing:1px}.owner-secondary-row b{font-size:17px;margin-top:7px}.admin-app .panel{border-radius:15px;border-color:#e1e5eb;box-shadow:0 7px 22px #11182708}.generated-credential-note{padding:12px 13px;border-radius:11px;background:#f4f7fa;border:1px solid #e0e6ee}.generated-credential-note b{display:block;font-size:12px;color:#243043}.generated-credential-note span{display:block;color:#7c8795;font-size:10px;margin-top:3px}.admin-app .mobile-scrim{z-index:90;background:#0b1220aa}.admin-app .mobile-drawer{z-index:100;position:fixed;left:14px;top:14px;bottom:14px;width:min(330px,calc(100vw - 28px));background:#101a2a;color:#fff;border:1px solid #2a374b;border-radius:20px;padding:16px;box-shadow:0 25px 70px #0008;overflow:auto}.mobile-drawer .nav-item{display:flex;align-items:center;gap:10px;width:100%;padding:12px 11px;border:0;border-radius:10px;background:transparent;color:#b9c4d3;text-align:left}.mobile-drawer .nav-item.active{background:#ffffff0d;color:#fff}
@media(max-width:700px){.admin-app .admin-sidebar{height:64px;padding:0 14px}.admin-app .brand-mark{width:34px;height:34px}.admin-app .sidebar-brand small{display:none}.admin-app .workspace-card{padding:7px 9px;margin-right:52px}.admin-app .workspace-card small{display:none}.admin-app .workspace-card strong{font-size:11px;max-width:100px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.admin-app .admin-main{padding:82px 13px 30px}.admin-app .admin-page-header{align-items:center;margin-bottom:15px}.admin-app .page-heading h2{font-size:26px}.admin-app .page-heading p{font-size:11px}.admin-app .owner-welcome{padding:21px 18px;border-radius:17px;display:block}.admin-app .owner-welcome h1{font-size:25px}.owner-primary-action{width:100%;margin-top:17px}.owner-stat-row{grid-template-columns:repeat(3,1fr);gap:7px}.owner-stat{padding:13px 11px;border-radius:13px}.owner-stat b{font-size:20px}.owner-stat span,.owner-stat small{font-size:9px}.owner-quick-grid{grid-template-columns:1fr 1fr;gap:8px}.owner-quick-grid button{padding:14px;border-radius:13px}.owner-secondary-row{grid-template-columns:1fr;gap:8px}.owner-attention{padding:15px 14px}.admin-app .modal{width:min(100%,520px);max-height:92vh;border-radius:18px}}
'''
    css.write_text(css_text,encoding='utf-8')
print('Owner v2 applied')
